// Worker session 运行指示圆点。
//
// 视觉照搬 QwenPaw console AgentStatusIndicator（实读）：8px 圆点 +
// statusPulse 1.2s 呼吸（opacity 1↔0.35 + box-shadow 扩散）+ Tooltip +
// prefers-reduced-motion 降级关动画。色板按产品：
// 蓝 #3b82f6 = 运行中（呼吸）/ 绿 #52c41a = 运行完成（常亮）/ 灰 = 无任务（常亮）
// 呼吸动画走 CSS class（wb-session-dot.running）而非内联 animation——
// 内联样式无法被 @media (prefers-reduced-motion) 覆盖，class 可以。

import type * as ReactNS from "react";

import type { WorkerSessionState } from "../workerSessionState";
import { useT } from "../i18n";
import { WbTooltip } from "./WbTooltip";

const host = window.QwenPaw.host;
const React: typeof ReactNS = host.React;

const STATE_COLOR: Record<WorkerSessionState, string> = {
  running: "#3b82f6",
  done: "#52c41a",
  idle: "#c0c4cc",
};

const STATE_TEXT: Record<WorkerSessionState, string> = {
  running: "运行中",
  done: "运行完成",
  idle: "无任务",
};

export default function WorkerSessionDot({
  state,
  size = 8,
  corner = false,
}: {
  state: WorkerSessionState;
  size?: number;
 /** （灯在头像角落）：absolute 挂右下 + 白描边环。 */
  corner?: boolean;
}) {
  const tr = useT();
  // key={state} 强制重挂载：状态切换时 Tooltip 重新定位/刷新文案。
  // role="img" + aria-label：屏幕阅读器读出状态（dashboard #127 合并时
  // 维护者 a11y 修复同款，beta.13.2 对齐）。
  return (
    <WbTooltip key={state} title={tr(STATE_TEXT[state])}>
      <span
        role="img"
        aria-label={tr(STATE_TEXT[state])}
        className={state === "running" ? "wb-session-dot running" : "wb-session-dot"}
        style={
          corner
            ? {
                position: "absolute",
                right: -2,
                bottom: -2,
                display: "inline-block",
                width: size,
                height: size,
                borderRadius: "50%",
                background: STATE_COLOR[state],
                border: "1.5px solid #fff",
                boxShadow: "0 0 0 0.5px rgba(0,0,0,0.15)",
                pointerEvents: "auto",
              }
            : {
                display: "inline-block",
                width: size,
                height: size,
                borderRadius: "50%",
                background: STATE_COLOR[state],
                flexShrink: 0,
                marginLeft: 6,
                verticalAlign: "middle",
              }
        }
      />
    </WbTooltip>
  );
}

/**
 * 可选状态圆点：state 缺省（旧 controller 未派生 / Worker 不在树内）→
 * 不渲染（外层行高与布局不变）；有 state → 复用 WorkerSessionDot。
 * 管理页团队行 / 独立 Worker 行 / Worker 详情头三处共用同一门控。
 */
export function SessionDot({ state }: { state?: WorkerSessionState }) {
  if (!state) return null;
  return <WorkerSessionDot state={state} />;
}
