// WorkflowBoard 巨石拆分 · 事件级干预（InterventionActions）/ 中断横幅
// （InterruptsBlock）/ 循环计划块（LoopBlock）。
// 逐字自 components/WorkflowBoard.tsx 搬移；仅加 `export`。

import type * as ReactNS from "react";
import {
  type WorkflowEvent,
  type WorkflowInterrupt,
  type TaskDetail,
  pauseProject,
  resumeProject,
  completeProject,
  replanProject,
  sendRoomMessage,
} from "../api";
import { useThemeColors } from "../theme";
import { useT } from "../i18n";
import { parseOptions } from "../pending/parse";
import { selectCompanionIds } from "../pending/tally";
import { usePendingStore } from "../pending/store";
import {
  PauseIcon,
  PlayIcon,
  CheckIcon,
  TodoIcon,
  WarnIcon,
  RefreshIcon,
} from "../components/icons";
import { statusMeta, replanSeedJson } from "./helpers";

const host = window.QwenPaw.host;
const React = host.React;
const antd = host.antd;

/** 事件级干预（上游已合并）：Pause / Resume / 完成 / 重规划 + interrupts 渲染。
 * 成功后回调 onDone 刷新工作流。门控语义对齐 Controller（v1.2.3 源码）：
 * active/planning 可 pause；paused interrupt（action_request.resume +
 * allow_accept）可 resume；active/planning 可 complete（上游要求全任务终态，
 * 否则 409 带原因透传）；active + dag + 无 in-progress 节点可 replan。 */
export function InterventionActions({
  ev,
  onDone,
}: {
  ev: WorkflowEvent;
  onDone?: () => void;
}) {
  const tr = useT();
  const [pauseOpen, setPauseOpen] = React.useState(false);
  const [reason, setReason] = React.useState("");
  const [completeOpen, setCompleteOpen] = React.useState(false);
  const [replanOpen, setReplanOpen] = React.useState(false);
  const [replanText, setReplanText] = React.useState("");
  const [busy, setBusy] = React.useState<
    "pause" | "resume" | "complete" | "replan" | null
  >(null);

  const resumeInterrupt = (ev.interrupts || []).find(
    (it) => it.action_request?.action === "resume" && it.config?.allow_accept,
  );
  const canPause = ev.status === "active" || ev.status === "planning";
  const canComplete = ev.status === "active" || ev.status === "planning";
  const canReplan =
    ev.status === "active" &&
    (!ev.plan_type || ev.plan_type === "dag") &&
    !((ev.nodes || []).some((n) => n.status === "in-progress"));

  const handlePause = async () => {
    setBusy("pause");
    try {
      await pauseProject(ev.runId, reason.trim() || undefined);
      antd.message.success(tr("项目已暂停"));
      setPauseOpen(false);
      setReason("");
      onDone?.();
    } catch (e) {
      antd.message.error(e instanceof Error ? e.message : tr("暂停失败"));
    } finally {
      setBusy(null);
    }
  };

  const handleResume = async () => {
    setBusy("resume");
    try {
      await resumeProject(ev.runId);
      antd.message.success(tr("项目已恢复"));
      onDone?.();
    } catch (e) {
      antd.message.error(e instanceof Error ? e.message : tr("恢复失败"));
    } finally {
      setBusy(null);
    }
  };

  const handleComplete = async () => {
    setBusy("complete");
    try {
      await completeProject(ev.runId);
      antd.message.success(tr("项目已标记完成"));
      setCompleteOpen(false);
      onDone?.();
    } catch (e) {
      antd.message.error(
        `${tr("完成失败")}${e instanceof Error ? `：${e.message}` : ""}`,
      );
    } finally {
      setBusy(null);
    }
  };

  const openReplan = () => {
    setReplanText(replanSeedJson(ev));
    setReplanOpen(true);
  };

  const handleReplan = async () => {
    let parsed: unknown;
    try {
      parsed = JSON.parse(replanText);
    } catch {
      antd.message.error(tr("任务 JSON 解析失败，请检查格式"));
      return;
    }
    if (!Array.isArray(parsed)) {
      antd.message.error(tr("任务必须是 JSON 数组（[{taskId, ...}]）"));
      return;
    }
    for (const [i, t] of (parsed as unknown[]).entries()) {
      const tid =
        t && typeof t === "object"
          ? (t as Record<string, unknown>).taskId
          : undefined;
      if (typeof tid !== "string" || !tid.trim()) {
        antd.message.error(tr("第 {n} 项缺少 taskId", { n: i + 1 }));
        return;
      }
    }
    setBusy("replan");
    try {
      await replanProject(ev.runId, parsed);
      antd.message.success(tr("项目已重规划"));
      setReplanOpen(false);
      onDone?.();
    } catch (e) {
      antd.message.error(
        `${tr("重规划失败")}${e instanceof Error ? `：${e.message}` : ""}`,
      );
    } finally {
      setBusy(null);
    }
  };

  if (
    !canPause &&
    !canComplete &&
    !canReplan &&
    !resumeInterrupt &&
    !(ev.interrupts || []).length
  ) {
    return null;
  }

  return (
    <>
      {canPause ? (
        <antd.Button
          size="small"
          loading={busy === "pause"}
          onClick={() => setPauseOpen(true)}
          style={{ color: "#fa8c16" }}
        >
          <PauseIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("暂停")}
        </antd.Button>
      ) : null}
      {resumeInterrupt ? (
        <antd.Button
          size="small"
          type="primary"
          loading={busy === "resume"}
          onClick={() => void handleResume()}
        >
          <PlayIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("恢复")}
        </antd.Button>
      ) : null}
      {canComplete ? (
        <antd.Button
          size="small"
          loading={busy === "complete"}
          onClick={() => setCompleteOpen(true)}
          style={{ color: "#52c41a" }}
        >
          <CheckIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("完成")}
        </antd.Button>
      ) : null}
      {canReplan ? (
        <antd.Button
          size="small"
          loading={busy === "replan"}
          onClick={openReplan}
          style={{ color: "#1677ff" }}
        >
          <TodoIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("重规划")}
        </antd.Button>
      ) : null}
      <antd.Modal
        open={pauseOpen}
        title={`${tr("暂停项目")} — ${ev.title || ev.runId}`}
        okText={tr("确认暂停")}
        cancelText={tr("取消")}
        confirmLoading={busy === "pause"}
        onOk={() => void handlePause()}
        onCancel={() => setPauseOpen(false)}
        width={440}
      >
        <antd.Input.TextArea
          value={reason}
          onChange={(e: ReactNS.ChangeEvent<HTMLTextAreaElement>) =>
            setReason(e.target.value)
          }
          aria-label={tr("暂停原因（可选，将通知团队）")}
          placeholder={tr("暂停原因（可选，将通知团队）")}
          rows={3}
          maxLength={200}
        />
      </antd.Modal>
      <antd.Modal
        open={completeOpen}
        title={`${tr("完成项目")} — ${ev.title || ev.runId}`}
        okText={tr("确认完成")}
        cancelText={tr("取消")}
        confirmLoading={busy === "complete"}
        onOk={() => void handleComplete()}
        onCancel={() => setCompleteOpen(false)}
        width={440}
      >
        <div style={{ fontSize: 13, lineHeight: 1.7 }}>
          {tr(
            "确认将项目标记为已完成？所有任务须已终止（完成/失败/阻塞/取消），否则上游会拒绝。完成后会通知项目群。",
          )}
        </div>
      </antd.Modal>
      <antd.Modal
        open={replanOpen}
        title={`${tr("重规划项目（编辑任务 DAG）")} — ${ev.title || ev.runId}`}
        okText={tr("提交重规划")}
        cancelText={tr("取消")}
        confirmLoading={busy === "replan"}
        onOk={() => void handleReplan()}
        onCancel={() => setReplanOpen(false)}
        width={560}
      >
        <div style={{ fontSize: 12, color: "#999", marginBottom: 8, lineHeight: 1.6 }}>
          {tr(
            "已按当前任务预填（不含 status）：保留的 taskId 省略字段将继承旧值，新增任务只需 taskId（可选 title/assignedTo/dependsOn）。重规划后项目通知群内。",
          )}
        </div>
        <antd.Input.TextArea
          value={replanText}
          onChange={(e: ReactNS.ChangeEvent<HTMLTextAreaElement>) =>
            setReplanText(e.target.value)
          }
          aria-label={tr("重规划项目（编辑任务 DAG）")}
          rows={12}
          style={{ fontFamily: "monospace", fontSize: 12 }}
        />
      </antd.Modal>
    </>
  );
}

/** 单条 interrupt 的介入操作区（P0 人工介入闭环 Stage 3）：
 * 有 options → 选项按钮（recommended 高亮）；无 options → 单行输入
 * + 提交；action_request=resume 且 allow_accept → 额外「恢复项目」
 * （复用 resumeProject）；「去房间」深链恒给（ev.room_id 存在时）。
 * 提交 = 向项目房间发 `【干预答复】` 消息（Worker 侧识别前缀消费）
 * + 本地 resolve（同 taskId 跨源同伴一并清）。已答 → 只读回显，
 * 不重复提交。pendingId 口径与 WorkbenchPageData.syncPendingInterrupts
 * 一致：`${runId}:${it.id}:${it.value}`。 */
export function InterruptActions({
  ev,
  it,
  onDone,
  onGotoRoom,
}: {
  ev: WorkflowEvent;
  it: WorkflowInterrupt;
  onDone?: () => void;
  onGotoRoom?: (roomId: string) => void;
}) {
  const tr = useT();
  const pending = usePendingStore();
  const [answer, setAnswer] = React.useState("");
  const [busy, setBusy] = React.useState(false);

  const pendingId = `${ev.runId}:${it.id}:${it.value}`;
  const resolution = pending.resolutions.find((r) => r.id === pendingId);
  const options = parseOptions(it.description || it.value);
  const canResume =
    it.action_request?.action === "resume" && !!it.config?.allow_accept;

  const submit = async (text: string) => {
    const body = text.trim();
    if (!body || busy) return;
    setBusy(true);
    try {
      // 没有可发送的房间 → 明确报错，绝不静默「已介入」（那只是本地记账）。
      if (!ev.room_id) {
        throw new Error(tr("该项目没有可发送的房间，无法在此提交——请到项目房间或工作流页处理"));
      }
      await sendRoomMessage(ev.room_id, `【干预答复】${body}`);
      const item = pending.items.find((x) => x.id === pendingId);
      // sent = 已发送待处理（不是已处理）；Controller 仍报同一 interrupt 时会重新出现。
      pending.resolve(pendingId, {
        status: "sent",
        answer: body.slice(0, 200),
      });
      // 跨源同伴一并清（同 taskId 的其它待办项）。
      if (item) {
        for (const cid of selectCompanionIds(pending.items, item)) {
          pending.resolve(cid, {
            status: "answered",
            answer: body.slice(0, 200),
          });
        }
      }
      setAnswer("");
      onDone?.();
    } catch (e) {
      antd.message.error(
        e instanceof Error ? e.message : tr("发送失败，请重试"),
      );
    } finally {
      setBusy(false);
    }
  };

  if (resolution) {
    return (
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 5,
          marginTop: 6,
          fontSize: 12,
        }}
      >
        <CheckIcon size={12} />
        <span style={{ opacity: 0.75 }}>
          {resolution.status === "sent" ? tr("已提交，等待处理") : tr("已介入")}
          {resolution.answer ? `：${resolution.answer}` : ""}
        </span>
      </div>
    );
  }

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 6,
        marginTop: 6,
        flexWrap: "wrap",
      }}
    >
      {options && options.length > 0 ? (
        options.map((o) => (
          <antd.Button
            key={o.id}
            size="small"
            type={o.recommended ? "primary" : "default"}
            loading={busy}
            onClick={() => void submit(o.label)}
            style={o.recommended ? { color: "#fff" } : undefined}
          >
            {o.label}
          </antd.Button>
        ))
      ) : (
        <>
          <antd.Input
            size="small"
            value={answer}
            onChange={(e: ReactNS.ChangeEvent<HTMLInputElement>) =>
              setAnswer(e.target.value)
            }
            onPressEnter={() => void submit(answer)}
            aria-label={tr("填写介入意见…")}
            placeholder={tr("填写介入意见…")}
            style={{ width: 220 }}
          />
          <antd.Button
            size="small"
            type="primary"
            loading={busy}
            onClick={() => void submit(answer)}
            /* 橙色容器里 primary 按钮会继承父级橙字（蓝底橙字不可读）→ 显式白字 */
            style={{ color: "#fff" }}
          >
            {tr("提交")}
          </antd.Button>
        </>
      )}
      {canResume ? (
        <antd.Button
          size="small"
          loading={busy}
          onClick={() => {
            void (async () => {
              setBusy(true);
              try {
                await resumeProject(ev.runId);
                antd.message.success(tr("项目已恢复"));
                onDone?.();
              } catch (e) {
                antd.message.error(
                  e instanceof Error ? e.message : tr("恢复失败"),
                );
              } finally {
                setBusy(false);
              }
            })();
          }}
        >
          <PlayIcon
            size={12}
            style={{ verticalAlign: "-1px", marginRight: 3 }}
          />{" "}
          {tr("恢复项目")}
        </antd.Button>
      ) : null}
      {ev.room_id && onGotoRoom ? (
        <antd.Button size="small" onClick={() => onGotoRoom(ev.room_id)}>
          {tr("去房间")}
        </antd.Button>
      ) : null}
    </div>
  );
}

/** 中断横幅：展示 interrupts 与暂停原因（paused interrupt）。
 * （13.12 「顶上三个 ⚠ blocked 只显示 '⚠ blocked'
 * 有点突兀」）：interrupt.id 即 task_id（实盘某项目 3 条 blocked
 * interrupt id=...-03/-04/-07 与 tasks_detail task_id 一一对应）→
 * 横幅带任务短编号 + 当前状态 + 分配 Worker，可定位到具体任务。
 * 无 task 匹配（interrupt 非任务维度）→ 保持原样。
 * ev 传入时（拓扑详情/决策抽屉）每条横幅挂 InterruptActions 介入区。 */
export function InterruptsBlock({
  interrupts,
  pauseReason,
  tasks,
  ev,
  onDone,
  onGotoRoom,
}: {
  interrupts: WorkflowInterrupt[];
  pauseReason?: string;
  tasks?: TaskDetail[];
  /** 传入时每条横幅挂 InterruptActions 介入操作区（缺省=只读横幅，
   * 如 AgentActivityTrack 抽屉未带事件上下文的旧调用点）。 */
  ev?: WorkflowEvent;
  onDone?: () => void;
  onGotoRoom?: (roomId: string) => void;
}) {
  const tr = useT();
  const t = useThemeColors(); 
  if (interrupts.length === 0) return null;
  const taskById = new Map<string, TaskDetail>();
  (tasks || []).forEach((tk) => {
    if (tk.task_id) taskById.set(tk.task_id, tk);
  });
  const shortId = (id: string) => {
    const parts = id.split("-");
    return parts.length > 1 ? parts[parts.length - 1] : id;
  };
  return (
    <div style={{ display: "grid", gap: 6, marginTop: 8 }}>
      {interrupts.map((it) => {
        const task = taskById.get(it.id);
        const detail: string[] = [];
        if (task) {
          detail.push(tr("任务 {n}", { n: shortId(it.id) }));
          if (task.status) detail.push(task.status);
          if (task.assigned_to) detail.push(task.assigned_to);
        }
        // 「要处理什么」= 任务标题（summary）+ 状态 + 原因；只有任务短号时读者无从判断。
        const taskTitle = task
          ? String(task.summary || "").trim() || task.task_id || shortId(it.id)
          : shortId(it.id);
        const reason =
          String(it.description || "").trim() ||
          String(pauseReason || "").trim() ||
          (task && String((task as unknown as Record<string, unknown>).result_note || "").trim()) ||
          "";
        return (
          <div
            key={it.id || it.value}
            style={{
              display: "grid",
              gap: 4,
              fontSize: 12,
              padding: "8px 10px",
              borderRadius: 8,
              border: "1px solid #fa8c16",
              // 深色档：6% 橙底太淡 / 深橙字不可读 → 加浓 + 亮向
              background: t.mode === "dark" ? "rgba(250,140,22,0.14)" : "rgba(250, 140, 22, 0.06)",
              color: t.mode === "dark" ? "#faad14" : "#d46b08",
            }}
          >
            <div style={{ fontWeight: 600, display: "flex", alignItems: "center", gap: 5, flexWrap: "wrap" }}>
              {it.value === "paused" ? <PauseIcon size={12} /> : <WarnIcon size={12} />}
              <span>
                {it.value === "paused" ? tr("项目已暂停") : it.value === "blocked" ? tr("阻塞") : it.value}
              </span>
              <span style={{ fontWeight: 400, opacity: 0.9 }}>· {taskTitle}</span>
              {task && task.status ? (
                <antd.Tag color="orange" style={{ marginInlineEnd: 0, fontSize: 10, lineHeight: "16px" }}>
                  {task.status}
                </antd.Tag>
              ) : null}
              {task && task.assigned_to ? (
                <span style={{ fontWeight: 400, opacity: 0.75 }}>{task.assigned_to}</span>
              ) : null}
            </div>
            {reason ? (
              <div style={{ opacity: 0.85 }}>
                {tr("原因：")}
                {reason}
              </div>
            ) : (
              <div style={{ opacity: 0.75 }}>
                {tr("未提供原因——在下方填写你的处理意见，发到项目房间由 Leader 跟进。")}
              </div>
            )}
            {detail.length > 0 ? (
              <div style={{ opacity: 0.7, fontSize: 11 }}>
                {tr("任务 {n}", { n: shortId(it.id) })}
              </div>
            ) : null}
            {ev ? (
              <InterruptActions
                ev={ev}
                it={it}
                onDone={onDone}
                onGotoRoom={onGotoRoom}
              />
            ) : null}
          </div>
        );
      })}
    </div>
  );
}

/** Loop 计划块（plan_type=loop 项目的迭代进度/停止条件/任务图）。 */
export function LoopBlock({
  loop,
}: {
  loop: NonNullable<WorkflowEvent["loop"]>;
}) {
  const tr = useT();
  const t = useThemeColors(); 
  const cur = typeof loop.current_iteration === "number" ? loop.current_iteration : 0;
  const max = typeof loop.max_iterations === "number" ? loop.max_iterations : 0;
  const pct = max > 0 ? Math.min(100, Math.round((cur / max) * 100)) : 0;
  return (
    <div
      style={{
        display: "grid",
        gap: 6,
        marginTop: 8,
        padding: "8px 10px",
        borderRadius: 8,
        border: `1px solid ${t.border}`,
        background: t.hoverBg,
        fontSize: 12,
      }}
    >
      <div style={{ fontWeight: 700 }}>
        <RefreshIcon size={12} style={{ verticalAlign: "-1px", marginRight: 3 }} /> {tr("循环任务")}
        {loop.status ? (
          <span style={{ marginLeft: 8, fontWeight: 400, opacity: 0.7 }}>
            {loop.status}
          </span>
        ) : null}
        {max > 0 ? (
          <span style={{ float: "right", fontWeight: 400, opacity: 0.7 }}>
            {cur}/{max}
          </span>
        ) : null}
      </div>
      {max > 0 ? (
        <div
          style={{
            height: 6,
            borderRadius: 3,
            background: t.hoverBg, // 进度槽
            overflow: "hidden",
          }}
        >
          <div
            style={{
              height: "100%",
              width: `${pct}%`,
              background: "#722ed1",
              borderRadius: 3,
            }}
          />
        </div>
      ) : null}
      {loop.goal ? (
        <div style={{ opacity: 0.8 }}>目标：{loop.goal}</div>
      ) : null}
      {loop.stop_condition ? (
        <div style={{ opacity: 0.7 }}>停止条件：{loop.stop_condition}</div>
      ) : null}
      {(loop.tasks || []).length > 0 ? (
        <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
          {(loop.tasks || []).map((t, i) => {
            const st = statusMeta(String(t.status || ""));
            return (
              <antd.Tag key={t.task_id || i} color={st.color} style={{ margin: 0, fontSize: 11 }}>
                {t.title || t.task_id || `步骤 ${i + 1}`}
              </antd.Tag>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}
